-- ============================================================================
--  3B core verify 98번(md5) FAIL 진단 v2 — 100% 읽기 전용 (WITH + SELECT 한 문장)
--
--  · DB 에 저장된 hosted_tournament_preliminary_standings_core 본문(prosrc)에서
--    98번과 같은 방식으로 계산식 구간을 잘라 원문과 비교한다.
--  · 3B 원문 계산식은 ASCII base64 한 줄로 넣고 DB 안에서 복원한다
--    (달러 인용 · 세미콜론 · 한글이 없어 붙여넣기 과정에서 바뀌거나 쪼개지지 않는다).
--  · ⏎ = LF, ␍ = CR 로 문맥을 보여준다.
--  · 18행은 v1 실행 실패 때 계산식 조각이 테이블을 만들지 않았는지 보는 안전 점검이다.
--
--  결과: n / k / v 표 한 개(18행). 전체를 그대로 붙여넣고 1회 실행.
-- ============================================================================
with
src as (
    select prosrc as s
      from pg_catalog.pg_proc
     where oid = to_regprocedure('public.hosted_tournament_preliminary_standings_core(uuid)')
),
mk as (
    -- 끝 표시의 세미콜론은 chr(59) 로 만든다(편집기 문장 분리 방지 — 이 파일의 세미콜론은 맨 끝 1개뿐).
    select '    with grp as ('::text as st, ('     where g.tournament_id = v_tid and g.group_type = ''placement''' || chr(59))::text as en
),
seg as (
    select strpos(src.s, mk.st) as p0, strpos(src.s, mk.en) as p1,
           substr(src.s, strpos(src.s, mk.st),
                  strpos(src.s, mk.en) + length(mk.en) - strpos(src.s, mk.st)) as a
      from src, mk
),
orig as (
    select convert_from(decode('', 'base64'), 'UTF8') as e
),
norm as (
    select seg.a, orig.e,
           btrim(regexp_replace(regexp_replace(seg.a, '--[^' || chr(10) || ']*', ' ', 'g'), '\s+', ' ', 'g')) as ta,
           btrim(regexp_replace(regexp_replace(orig.e, '--[^' || chr(10) || ']*', ' ', 'g'), '\s+', ' ', 'g')) as te
      from seg, orig
),
fd as (
    select norm.a, norm.e, norm.ta, norm.te,
           (select min(i) from generate_series(1, greatest(length(norm.a), length(norm.e))) as g(i)
             where substr(norm.a, g.i, 1) is distinct from substr(norm.e, g.i, 1)) as d_raw,
           (select min(i) from generate_series(1, greatest(length(norm.ta), length(norm.te))) as g(i)
             where substr(norm.ta, g.i, 1) is distinct from substr(norm.te, g.i, 1)) as d_tok
      from norm
),
vis as (
    select fd.*,
           replace(replace(substr(fd.a,  greatest(coalesce(fd.d_raw, 1) - 60, 1), 140), chr(13), '␍'), chr(10), '⏎') as ctx_a,
           replace(replace(substr(fd.e,  greatest(coalesce(fd.d_raw, 1) - 60, 1), 140), chr(13), '␍'), chr(10), '⏎') as ctx_e,
           substr(fd.ta, greatest(coalesce(fd.d_tok, 1) - 60, 1), 140) as tctx_a,
           substr(fd.te, greatest(coalesce(fd.d_tok, 1) - 60, 1), 140) as tctx_e
      from fd
),
rows as (
    select  1 as n, 'core 함수 존재 · 구간 추출 성공' as k,
            ((select count(*) from src) = 1 and coalesce((select p0 > 0 and p1 > 0 from seg), false))::text as v
    union all select  2, 'EXPECTED MD5 (3B 원문, LF)', '5dc86cfc40c3b084f3ff17657929da5f'
    union all select  3, 'ACTUAL MD5 (DB 저장 core 구간)', (select md5(vis.a) from vis)
    union all select  4, 'PASTED/DECODED 원문 MD5 (= EXPECTED 이어야 정상)', (select md5(vis.e) from vis)
    union all select  5, 'length chars — actual / expected', (select length(vis.a) || ' / ' || length(vis.e) from vis)
    union all select  6, 'length bytes — actual / expected', (select octet_length(vis.a) || ' / ' || octet_length(vis.e) from vis)
    union all select  7, 'CR 개수 — actual / expected',
            (select (length(vis.a) - length(replace(vis.a, chr(13), ''))) || ' / '
                    || (length(vis.e) - length(replace(vis.e, chr(13), ''))) from vis)
    union all select  8, 'ACTUAL MD5 (CR 제거 후)', (select md5(replace(vis.a, chr(13), '')) from vis)
    union all select  9, '줄 끝 공백 있는 줄 수 — actual / expected',
            (select (select count(*) from regexp_split_to_table(replace(vis.a, chr(13), ''), chr(10)) as l(x) where l.x ~ '[ \t]+$')
                    || ' / ' ||
                    (select count(*) from regexp_split_to_table(vis.e, chr(10)) as l(x) where l.x ~ '[ \t]+$') from vis)
    union all select 10, 'TOKEN MD5 expected (주석 제거 + 공백 정규화)', 'b225df53c40f3295531324e96e269fa9'
    union all select 11, 'TOKEN MD5 actual', (select md5(vis.ta) from vis)
    union all select 12, '원문 첫 차이 위치 (없으면 none)', (select coalesce(vis.d_raw::text, 'none') from vis)
    union all select 13, '원문 첫 차이 문맥 — actual', (select case when vis.d_raw is null then '-' else vis.ctx_a end from vis)
    union all select 14, '원문 첫 차이 문맥 — expected', (select case when vis.d_raw is null then '-' else vis.ctx_e end from vis)
    union all select 15, '토큰 첫 차이 위치 (없으면 none)', (select coalesce(vis.d_tok::text, 'none') from vis)
    union all select 16, '토큰 첫 차이 문맥 — actual / expected',
            (select case when vis.d_tok is null then '-' else vis.tctx_a || '   ||   ' || vis.tctx_e end from vis)
    union all select 17, 'CLASSIFICATION', (select case
            when md5(vis.a) = '5dc86cfc40c3b084f3ff17657929da5f' then 'MATCH (원문 동일 — 98 FAIL 의 다른 원인 확인 필요)'
            when md5(replace(vis.a, chr(13), '')) = '5dc86cfc40c3b084f3ff17657929da5f' then 'CRLF ONLY'
            when md5(vis.ta) = 'b225df53c40f3295531324e96e269fa9' then 'WHITESPACE/COMMENT ONLY'
            else 'TOKEN DIFFERENCE'
        end from vis)
    union all select 18, '안전 점검: v1 실패로 생긴 테이블 없음 (v_groups / v_place)',
            (select case when count(*) = 0 then 'none (정상)' else string_agg(n.nspname || '.' || c.relname, ', ') end
               from pg_catalog.pg_class c join pg_catalog.pg_namespace n on n.oid = c.relnamespace
              where c.relname in ('v_groups', 'v_place'))
)
select rows.n, rows.k, rows.v from rows order by rows.n;
